source_texts.invoice_boundary_project:
pub fn format_invoice(subtotal: i64, discount: i64) -> String {
    let net = subtotal - discount;
    format!("subtotal={subtotal}|discount={discount}|net={net}")
}

mod formatting;
mod pricing;

use formatting::format_invoice;
use pricing::invoice_discount;
use std::io::{self, Read};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let subtotal: i64 = input.trim().parse().unwrap();
    let discount = invoice_discount(subtotal);
    println!("{}", format_invoice(subtotal, discount));
}

pub fn invoice_discount(subtotal: i64) -> i64 {
    if subtotal >= 2000 { subtotal / 10 } else { 0 }
}

source_texts.capacity_state_project:
pub fn can_accept(used: i64, units: i64, capacity: i64) -> bool {
    used + units <= capacity
}

pub fn format_capacity(used: i64, deferred: i64) -> String {
    format!("used={used},deferred={deferred}")
}

mod allocation;
mod formatting;

use allocation::can_accept;
use formatting::format_capacity;
use std::io::{self, Read};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut lines = input.lines();
    let capacity: i64 = lines.next().unwrap().parse().unwrap();
    let count: usize = lines.next().unwrap().parse().unwrap();
    let (mut used, mut deferred) = (0, 0);
    for _ in 0..count {
        let mut parts = lines.next().unwrap().split('|');
        let id = parts.next().unwrap();
        let units: i64 = parts.next().unwrap().parse().unwrap();
        if can_accept(used, units, capacity) {
            println!("{id}:accept");
            used += units;
        } else {
            println!("{id}:defer");
            deferred += 1;
        }
    }
    println!("{}", format_capacity(used, deferred));
}

source_texts.normalized_tag_project:
pub fn format_tag_counts(unique_count: usize, duplicates: usize) -> String {
    format!("unique={unique_count},duplicates={duplicates}")
}

mod formatting;
mod normalization;

use formatting::format_tag_counts;
use normalization::normalize_tag;
use std::collections::HashSet;
use std::io::{self, Read};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut lines = input.lines();
    let count: usize = lines.next().unwrap().parse().unwrap();
    let mut seen = HashSet::new();
    let mut duplicates = 0;
    for _ in 0..count {
        let tag = lines.next().unwrap().to_string();
        let normalized = normalize_tag(&tag);
        if seen.contains(&normalized) { duplicates += 1; } else { seen.insert(normalized.clone()); println!("{normalized}"); }
    }
    println!("{}", format_tag_counts(seen.len(), duplicates));
}

pub fn normalize_tag(tag: &str) -> String {
    tag.to_lowercase()
}

source_texts.after_hours_routing_project:
pub fn format_counts(email: i64, chat: i64, pager: i64) -> String {
    format!("email={email},chat={chat},pager={pager}")
}

mod formatting;
mod routing;

use formatting::format_counts;
use routing::channel_for;
use std::io::{self, Read};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut lines = input.lines();
    let count: usize = lines.next().unwrap().parse().unwrap();
    let (mut email, mut chat, mut pager) = (0, 0, 0);
    for _ in 0..count {
        let mut parts = lines.next().unwrap().split('|');
        let team = parts.next().unwrap();
        let channel = channel_for(parts.next().unwrap(), parts.next().unwrap());
        match channel { "email" => email += 1, "chat" => chat += 1, _ => pager += 1 }
        println!("{team}:{channel}");
    }
    println!("{}", format_counts(email, chat, pager));
}

pub fn channel_for(severity: &str, after_hours: &str) -> &'static str {
    if severity == "low" {
        "email"
    } else if severity == "high" && after_hours != "yes" {
        "chat"
    } else {
        "pager"
    }
}

