after_hours_routing_project.source_text:
pub fn format_counts(email: i64, chat: i64, pager: i64) -> String {
    format!("email={email},chat={chat},pager={pager}")
}

mod formatting;
mod routing;

use formatting::format_counts;
use routing::channel_for;
use std::io::{self, Read};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut lines = input.lines();
    let count: usize = lines.next().unwrap().parse().unwrap();
    let (mut email, mut chat, mut pager) = (0, 0, 0);
    for _ in 0..count {
        let mut parts = lines.next().unwrap().split('|');
        let team = parts.next().unwrap();
        let channel = channel_for(parts.next().unwrap(), parts.next().unwrap());
        match channel { "email" => email += 1, "chat" => chat += 1, _ => pager += 1 }
        println!("{team}:{channel}");
    }
    println!("{}", format_counts(email, chat, pager));
}

pub fn channel_for(severity: &str, after_hours: &str) -> &'static str {
    if severity == "low" { "email" } else if severity == "high" && after_hours != "yes" { "chat" } else { "pager" }
}

